const require_defaults = require("../utils/defaults.js");
const require_index = require("../useResizeObserver/index.js");
let react = require("react");
//#region src/useElementSize/index.ts
const useElementSize = (target, options = require_defaults.defaultOptions) => {
	const { box = "content-box" } = options;
	const [width, setWidth] = (0, react.useState)(0);
	const [height, setHeight] = (0, react.useState)(0);
	require_index.useResizeObserver(target, ([entry]) => {
		const boxSize = box === "border-box" ? entry.borderBoxSize : box === "content-box" ? entry.contentBoxSize : entry.devicePixelContentBoxSize;
		if (boxSize) {
			setWidth(boxSize.reduce((acc, { inlineSize }) => acc + inlineSize, 0));
			setHeight(boxSize.reduce((acc, { blockSize }) => acc + blockSize, 0));
		} else {
			setWidth(entry.contentRect.width);
			setHeight(entry.contentRect.height);
		}
	}, options);
	return [width, height];
};
//#endregion
exports.useElementSize = useElementSize;
